# DP Calculation for T[L][r]
# T[L][r]: Count of strings of length L with sum congruent to r mod 3.
# Digits available: {0, 1, 2, 8}.
# Residues: R0={0} (1), R1={1} (1), R2={2, 8} (2).

L_max = 16
T = [[0] * 3 for _ in range(L_max + 1)]

# Base case T[0]: Empty string, sum 0
T[0][0] = 1

for L in range(L_max):
    for r in range(3):
        # T[L+1][0] receives contributions from T[L][r] * (count of digits d such that r+d=0 mod 3)

        # Contribution to T[L+1][0]
        if r == 0: # append 0 (R0)
            T[L+1][0] += T[L][r] * 1
        elif r == 1: # append 2 or 8 (R2)
            T[L+1][0] += T[L][r] * 2
        elif r == 2: # append 1 (R1)
            T[L+1][0] += T[L][r] * 1

        # Contribution to T[L+1][1]
        if r == 0: # append 1 (R1)
            T[L+1][1] += T[L][r] * 1
        elif r == 1: # append 0 (R0)
            T[L+1][1] += T[L][r] * 1
        elif r == 2: # append 2 or 8 (R2)
            T[L+1][1] += T[L][r] * 2

        # Contribution to T[L+1][2]
        if r == 0: # append 2 or 8 (R2)
            T[L+1][2] += T[L][r] * 2
        elif r == 1: # append 1 (R1)
            T[L+1][2] += T[L][r] * 1
        elif r == 2: # append 0 (R0)
            T[L+1][2] += T[L][r] * 1

# Calculate Total Count N = sum(N_L) for L=1 to 16
total_count = 0
for L in range(1, L_max + 1):
    # N_L = T[L][0] - T[L-1][0]
    N_L = T[L][0] - T[L-1][0]
    total_count += N_L

print(f"Correct Total Count (N): {total_count}")
